WITH flattened AS (SELECT id, plan, currency, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers) SELECT CASE WHEN tier_value >= 62 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, SUM(CASE WHEN currency = 'EUR' THEN tier_value ELSE 0 END) AS eur_tier_value, COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) AS enterprise_count, SUM(tier_value) FILTER (WHERE currency = 'THB') AS thb_total_tier_value, PERCENTILE_APPROX(tier_value, 0.9) AS tier_value_p90, ROUND(SUM(tier_value) / NULLIF(COUNT(CASE WHEN plan = 'basic' THEN 1 END), 0), 2) AS tier_value_per_basic, COUNT(CASE WHEN currency = 'EUR' THEN 1 END) AS eur_count FROM flattened GROUP BY CASE WHEN tier_value >= 62 THEN 'LARGE' ELSE 'SMALL' END ORDER BY thb_total_tier_value
